<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\PDO;
use App\Domain\Achievements\UserAchievement;use App\Domain\Achievements\UserAchievementRepository;use PDO;
final class PdoUserAchievementRepository implements UserAchievementRepository { public function __construct(private PDO $pdo) {} public function exists(string $userId, string $key): bool { $st=$this->pdo->prepare('SELECT 1 FROM user_achievements WHERE user_id=:u AND key_name=:k LIMIT 1'); $st->execute(['u'=>$userId,'k'=>$key]); return $st->fetch()!==false; } public function save(UserAchievement $achievement): void { $st=$this->pdo->prepare('INSERT INTO user_achievements (user_id,key_name,created_at) VALUES (:u,:k,:c) ON CONFLICT(user_id,key_name) DO NOTHING'); $st->execute(['u'=>$achievement->userId(),'k'=>$achievement->key(),'c'=>$achievement->createdAt()->format(DATE_ATOM)]); } public function listByUser(string $userId): array { $st=$this->pdo->prepare('SELECT user_id,key_name,created_at FROM user_achievements WHERE user_id=:u ORDER BY created_at ASC'); $st->execute(['u'=>$userId]); $rows=$st->fetchAll(); return array_map(fn(array $r)=>UserAchievement::reconstitute((string)$r['user_id'],(string)$r['key_name'],new \DateTimeImmutable((string)$r['created_at'])),$rows); }}
